@Component({
  selector: 'app-sidebar',
  imports: [CommonModule, RouterLink, RouterLinkActive, AppBrandComponent],
  templateUrl: './sidebar.component.html',
  styleUrl: './sidebar.component.scss',
})
export class SidebarComponent implements OnInit {
  protected readonly sidebarService = inject(SidebarService);
  protected readonly authService = inject(AuthService);
  private readonly router = inject(Router);
  protected readonly roleLabel = roleLabel;

  readonly perfilRoute = input('/ejecutivos/perfil');
  readonly menuItems = input<MenuItem[]>(defaultMenuItems);

  readonly openItems = signal<Set<string>>(new Set());

  readonly sections = computed(() => {
    const userRole = this.authService.currentUser()?.role;
    const items = this.menuItems().filter(item => {
      if (!item.roles) return true;
      return userRole ? item.roles.includes(userRole) : false;
    });

    const grouped = new Map<string, MenuItem[]>();
    for (const item of items) {
      const arr = grouped.get(item.section) ?? [];
      arr.push(item);
      grouped.set(item.section, arr);
    }
    return Array.from(grouped.entries()).map(([name, group]) => ({
      name,
      items: group,
    }));
  });

  ngOnInit(): void {
    this.openActiveParents();
    this.router.events
      .pipe(filter((e): e is NavigationEnd => e instanceof NavigationEnd))
      .subscribe(() => this.openActiveParents());
  }

  toggleItem(item: MenuItem): void {
    const key = item.route ?? item.label;
    this.openItems.update(current => {
      const next = new Set(current);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  }

  isExpanded(item: MenuItem): boolean {
    return this.openItems().has(item.route ?? item.label);
  }

  isChildActive(item: MenuItem): boolean {
    return this.hasActiveDescendant(item);
  }

  private hasActiveDescendant(item: MenuItem): boolean {
    const url = this.router.url;
    if (item.children) {
      for (const child of item.children) {
        if (child.route && url.startsWith(child.route)) return true;
        if (this.hasActiveDescendant(child)) return true;
      }
    }
    return false;
  }

  private openActiveParents(): void {
    const url = this.router.url;
    for (const item of this.menuItems()) {
      this.expandAncestors(item, url);
    }
  }

  private expandAncestors(item: MenuItem, url: string): boolean {
    if (!item.children) return false;
    let hasActive = false;
    for (const child of item.children) {
      if (child.route && url.startsWith(child.route)) {
        hasActive = true;
      } else if (this.expandAncestors(child, url)) {
        hasActive = true;
      }
    }
    if (hasActive) {
      this.openItems.update(current => new Set(current).add(item.route ?? item.label));
    }
    return hasActive;
  }

  onLogout(): void {
    this.authService.logout().subscribe(() => this.router.navigate(['/']));
  }
}
